const state={csrf:"",bootstrap:null,dashboard:null,projects:[],groups:[],repos:[],services:[],alerts:[],monitorEvents:[],environments:[],deployments:[],incidents:[],approvals:[],audit:[],contacts:[],whatsapp:null,githubSettings:null,aiSettings:null,ownerSettings:null,view:"overview",incidentFilter:"",pairingTimer:null,setupProjectId:"",setupStep:0};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const titles={setup:["GET STARTED","Guided setup"],overview:["OPERATIONS","Overview"],monitoring:["OPERATIONS","Monitoring"],incidents:["INCIDENT RESPONSE","Incidents"],approvals:["CONTROL GATE","Approvals"],deployments:["DELIVERY","Deployments"],projects:["CONFIGURATION","Projects"],channels:["CONNECTIONS","WhatsApp"],repositories:["SOURCE ACCESS","Repositories"],environments:["DELIVERY POLICY","Environments"],audit:["ASSURANCE","Audit trail"],system:["PLATFORM","System health"]};

async function api(path,options={}){const headers={"Content-Type":"application/json",...(options.headers||{})};if(state.csrf)headers["X-Echo-CSRF"]=state.csrf;const response=await fetch(path,{credentials:"same-origin",...options,headers});if(response.status===401)throw new Error("AUTH_REQUIRED");if(response.status===204)return null;const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data?.error?.message||`Request failed (${response.status})`);return data}
function escapeHTML(v=""){return String(v).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function when(v){if(!v||String(v).startsWith("0001-01-01"))return"—";const d=new Date(v);if(Number.isNaN(d.getTime()))return"—";return new Intl.DateTimeFormat(undefined,{dateStyle:"medium",timeStyle:"short"}).format(d)}
function badge(v){return `<span class="badge ${escapeHTML(v)}">${escapeHTML(String(v).replaceAll("_"," "))}</span>`}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2800)}
function empty(title,body){return `<div class="empty"><b>${escapeHTML(title)}</b>${escapeHTML(body)}</div>`}

async function boot(){try{state.bootstrap=await api("/api/v1/bootstrap");state.csrf=state.bootstrap.csrf||cookie("echo_csrf");$("#login").hidden=true;$("#shell").hidden=false;$("#environment").textContent=state.bootstrap.environment;await refreshAll();const requested=location.hash.slice(1);const destination=requested&&requested!=="overview"?requested:(setupStatus().complete?"overview":"setup");if(destination==="setup")state.setupStep=recommendedSetupStep();navigate(destination)}catch(err){if(err.message==="AUTH_REQUIRED"){showLogin()}else{$("#login-error").textContent=err.message}}}
function showLogin(){$("#login").hidden=false;$("#shell").hidden=true}
function cookie(name){return document.cookie.split("; ").find(v=>v.startsWith(name+"="))?.split("=").slice(1).join("=")||""}

async function refreshAll(){const requests=[api("/api/v1/dashboard"),api("/api/v1/projects"),api("/api/v1/groups"),api("/api/v1/repositories"),api("/api/v1/services"),api("/api/v1/monitor/alerts?status=open"),api("/api/v1/monitor/events"),api("/api/v1/environments"),api("/api/v1/deployments"),api("/api/v1/incidents"),api("/api/v1/approvals"),api("/api/v1/audit"),api("/api/v1/whatsapp"),api("/api/v1/settings/github"),api("/api/v1/settings/ai"),api("/api/v1/whatsapp/contacts"),api("/api/v1/settings/owner")];const [dashboard,projects,groups,repos,services,alerts,monitorEvents,environments,deployments,incidents,approvals,audit,whatsapp,githubSettings,aiSettings,contacts,ownerSettings]=await Promise.all(requests);Object.assign(state,{dashboard,projects:projects||[],groups:groups||[],repos:repos||[],services:services||[],alerts:alerts||[],monitorEvents:monitorEvents||[],environments:environments||[],deployments:deployments||[],incidents:incidents||[],approvals:approvals||[],audit:audit||[],whatsapp,githubSettings,aiSettings,contacts:contacts||[],ownerSettings});state.bootstrap.features.github=Boolean(githubSettings?.configured);state.bootstrap.features.ai=Boolean(aiSettings?.configured);state.bootstrap.features.owner=Boolean(ownerSettings?.configured);$("#incident-count").textContent=dashboard.openIncidents;$("#approval-count").textContent=dashboard.pendingApprovals;const alertCount=$("#alert-count");if(alertCount)alertCount.textContent=state.alerts.length;updateWhatsAppSummary();updateSetupProgress();monitorPairing()}
function updateWhatsAppSummary(){const connected=state.whatsapp?.status==="connected";$("#wa-dot").classList.toggle("online",connected);$("#wa-status").textContent=state.whatsapp?.status||"unknown"}
function monitorPairing(){clearTimeout(state.pairingTimer);if(!["pairing_requested","pairing","connecting"].includes(state.whatsapp?.status))return;state.pairingTimer=setTimeout(async()=>{try{state.whatsapp=await api("/api/v1/whatsapp");updateWhatsAppSummary();updateSetupProgress();if(["channels","setup"].includes(state.view))render();monitorPairing()}catch(err){if(err.message!=="AUTH_REQUIRED")toast(err.message)}},1000)}

function navigate(view){if(!titles[view])view="overview";state.view=view;location.hash=view;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$("#view-kicker").textContent=titles[view][0];$("#view-title").textContent=titles[view][1];$(".sidebar").classList.remove("open");render()}
function render(){const fn={setup:renderSetup,overview:renderOverview,monitoring:renderMonitoring,incidents:renderIncidents,approvals:renderApprovals,deployments:renderDeployments,projects:renderProjects,channels:renderChannels,repositories:renderRepositories,environments:renderEnvironments,audit:renderAudit,system:renderSystem}[state.view];$("#content").innerHTML=fn()}

function selectedSetupProject(){let project=state.projects.find(p=>p.id===state.setupProjectId);if(!project){project=state.projects.find(p=>p.enabled)||state.projects[0];state.setupProjectId=project?.id||""}return project}
function setupStatus(){const project=selectedSetupProject();const repos=project?state.repos.filter(r=>r.projectId===project.id&&r.enabled):[];const groups=project?state.groups.filter(g=>g.projectId===project.id&&g.enabled):[];const whatsapp=state.whatsapp?.status==="connected";const owner=Boolean(state.ownerSettings?.configured);const checks=[whatsapp,Boolean(project),repos.length>0,groups.length>0];return{project,repos,groups,whatsapp,owner,checks,count:checks.filter(Boolean).length,complete:checks.every(Boolean),intakeReady:whatsapp&&Boolean(project)&&groups.length>0,diagnosisReady:whatsapp&&owner&&Boolean(project)&&groups.length>0&&repos.length>0&&Boolean(state.bootstrap?.features?.github)&&Boolean(state.bootstrap?.features?.ai)}}
function recommendedSetupStep(){const s=setupStatus();const missing=s.checks.findIndex(v=>!v);return missing<0?4:missing}
function recommendedIntakeStep(){const s=setupStatus();if(!s.whatsapp)return 0;if(!s.project)return 1;if(!s.groups.length)return 3;return 4}
function updateSetupProgress(){const el=$("#setup-progress");if(el)el.textContent=`${setupStatus().count}/4`}
function setupCheck(done,label,detail){return `<div class="setup-check ${done?"done":"pending"}"><span>${done?"✓":"○"}</span><div><strong>${escapeHTML(label)}</strong><p>${escapeHTML(detail)}</p></div></div>`}
function setupBanner(){const s=setupStatus();if(s.complete)return"";return `<section class="setup-banner"><div><p class="eyebrow">SETUP IN PROGRESS · ${s.count} OF 4 COMPLETE</p><h2>Finish connecting Echo to your team</h2><p>${s.intakeReady?"Message intake is ready. Link a repository to enable code-aware diagnosis.":"The guided setup keeps the WhatsApp account, project, code and group in the right order."}</p></div><button class="button primary" data-resume-setup>Continue setup</button></section>`}

function renderSetup(){const s=setupStatus();const labels=["Connect WhatsApp","Choose project","Link code","Bind group","Test the flow"];const panels=[setupWhatsAppPanel(s),setupProjectPanel(s),setupRepositoryPanel(s),setupGroupPanel(s),setupTestPanel(s)];return `<section class="setup-hero"><div><p class="eyebrow">ONE SAFE PATH FROM REPORT TO FIX</p><h2>Set up Echo for a team</h2><p>A project is the hub that links one team’s WhatsApp groups to the exact repositories Echo may inspect. Echo’s number is connected once, then you add that contact to each group and bind the group here.</p></div><div class="setup-readiness"><span class="${s.intakeReady?"ready":"waiting"}">${s.intakeReady?"✓":"○"} Message intake</span><span class="${s.diagnosisReady?"ready":"waiting"}">${s.diagnosisReady?"✓":"○"} Code diagnosis</span></div></section><div class="setup-layout"><aside class="setup-stepper" aria-label="Setup steps">${labels.map((label,index)=>`<button class="setup-step ${state.setupStep===index?"active":""} ${index<4&&s.checks[index]?"complete":""}" data-setup-step="${index}"><span>${index<4&&s.checks[index]?"✓":index+1}</span><div><strong>${label}</strong><small>${["One dedicated Echo account","The team boundary","Read-only evidence first","Add in WhatsApp, bind here","Send a real @mention"][index]}</small></div></button>`).join("")}</aside><section class="card setup-panel">${panels[state.setupStep]||panels[0]}</section></div>`}
function setupWhatsAppPanel(s){const waiting=["pairing_requested","pairing","connecting"].includes(state.whatsapp?.status);let body;if(s.whatsapp){body=`<div class="setup-success"><span>✓</span><div><strong>Echo is connected</strong><p>${escapeHTML(state.whatsapp.deviceJid||"The dedicated WhatsApp account is online.")}</p></div></div><div class="setup-actions"><button class="button primary" data-setup-step="1">Continue to project</button><button class="button secondary" data-go="channels">Connection details</button></div>`}else if(state.whatsapp?.qrCode){body=`<div class="qr-box" aria-live="polite"><p>On the dedicated Echo phone, open <b>WhatsApp → Linked devices → Link a device</b>.</p><img src="/api/v1/whatsapp/qr.png?v=${encodeURIComponent(state.whatsapp.updatedAt||Date.now())}" alt="Fresh WhatsApp pairing QR code"><p class="muted">This QR rotates automatically and should be treated as a secret.</p></div>`}else{body=`<div class="setup-callout"><strong>${waiting?"Preparing a fresh QR code…":"Connect Echo’s dedicated WhatsApp account"}</strong><p>This is a one-time system connection. A fresh QR is created only after you request it, so the page never relies on a stale code.</p></div>${state.whatsapp?.lastError?`<p class="form-error">${escapeHTML(state.whatsapp.lastError)}</p>`:""}<button class="button primary" id="link-device" ${waiting?"disabled":""}>${waiting?"Preparing…":"Link device"}</button>`}return `<div class="setup-panel-head"><p class="eyebrow">STEP 1</p><h2>Connect Echo to WhatsApp</h2><p>Use a dedicated account that can be added to the team groups you want Echo to monitor.</p></div><div class="setup-panel-body">${body}</div>`}
function setupProjectPanel(s){return `<div class="setup-panel-head"><p class="eyebrow">STEP 2</p><h2>Create or choose a project</h2><p>The project is Echo’s safety boundary. It joins a team’s group conversation to only that team’s repositories and environments.</p></div><div class="setup-panel-body">${state.projects.length?`<label class="setup-project-picker">Project<select id="setup-project-select">${state.projects.map(p=>`<option value="${p.id}" ${p.id===s.project?.id?"selected":""}>${escapeHTML(p.name)}${p.enabled?"":" · disabled"}</option>`).join("")}</select></label><div class="setup-relations">${setupCheck(true,s.project?.name||"Project selected",s.project?.description||"Selected project")}${setupCheck(s.repos.length>0,`${s.repos.length} linked ${s.repos.length===1?"repository":"repositories"}`,s.repos.length?"Available for code evidence":"Add code in the next step")}${setupCheck(s.groups.length>0,`${s.groups.length} bound ${s.groups.length===1?"group":"groups"}`,s.groups.length?"Ready for mention intake":"Bind a group after linking code")}</div>`:empty("No projects yet","Create the team project that will own the repository and group relationships.")}<div class="setup-actions"><button class="button secondary" id="setup-create-project">Create new project</button>${s.project?`<button class="button primary" data-setup-step="2">Use ${escapeHTML(s.project.name)}</button>`:""}</div></div>`}
function setupRepositoryPanel(s){const github=Boolean(state.githubSettings?.configured);const list=s.repos.length?`<div class="setup-list">${s.repos.map(r=>`<div><span class="setup-list-icon">⌘</span><p><strong>${escapeHTML(r.owner)}/${escapeHTML(r.name)}</strong><small>${escapeHTML(r.role)} · ${r.readOnly?"read-only":"write gated"}</small></p>${badge(r.enabled?"enabled":"disabled")}</div>`).join("")}</div>`:empty("No repository linked","Echo can receive a report without code access, but it cannot investigate the codebase.");return `<div class="setup-panel-head"><p class="eyebrow">STEP 3</p><h2>Give Echo scoped code access</h2><p>Connect a fine-grained token limited to the repositories Echo may inspect. Keep repositories read-only until the investigation flow is proven.</p></div><div class="setup-panel-body">${s.project?`<div class="context-pill">Project <strong>${escapeHTML(s.project.name)}</strong></div>${github?`<div class="setup-success compact"><span>✓</span><div><strong>GitHub connected as ${escapeHTML(state.githubSettings.account||"your account")}</strong><p>The encrypted token is available to workers but is never returned to the browser.</p></div></div>${list}`:`<div class="setup-warning"><strong>Connect GitHub before linking code</strong><p>Enter a fine-grained personal access token here in Echo. It will be validated, encrypted and stored in MariaDB; only the encryption key remains in the server environment.</p></div>${list}`}<div class="setup-actions">${github?`<button class="button secondary" id="setup-add-repo">Link repository</button><button class="quiet" id="configure-github-token">Replace token</button>`:`<button class="button secondary" id="configure-github-token">Configure GitHub token</button>`}<button class="button primary" data-setup-step="3">${s.repos.length?"Continue to group":"Continue with intake only"}</button></div>`:`<div class="setup-warning"><strong>Choose a project first</strong><p>Repository access must belong to a project.</p></div><button class="button secondary" data-setup-step="1">Back to project</button>`}</div>`}
function setupGroupPanel(s){const bound=s.groups.length?`<div class="setup-list">${s.groups.map(g=>`<div><span class="setup-list-icon">⌁</span><p><strong>${escapeHTML(g.groupName)}</strong><small>${escapeHTML(g.groupJid)} · ${g.mentionRequired?"mention required":"all messages"}</small></p>${badge(g.enabled?"enabled":"disabled")}</div>`).join("")}</div>`:"";return `<div class="setup-panel-head"><p class="eyebrow">STEP 4</p><h2>Add Echo to the group, then bind it</h2><p>WhatsApp controls group membership. Echo can discover a group only after its connected account has been added to that group.</p></div><div class="setup-panel-body"><ol class="setup-instructions"><li><span>1</span><div><strong>Add Echo in WhatsApp</strong><p>Open the team group and add the dedicated Echo contact as a participant.</p></div></li><li><span>2</span><div><strong>Return here and discover groups</strong><p>Echo reads the joined group list from its own account.</p></div></li><li><span>3</span><div><strong>Bind the group to ${escapeHTML(s.project?.name||"a project")}</strong><p>Only real @mention metadata in enabled bindings will create incidents.</p></div></li></ol>${bound}${!s.whatsapp?`<div class="setup-warning"><strong>WhatsApp is not connected</strong><p>Complete step 1 before group discovery.</p></div>`:""}${!s.project?`<div class="setup-warning"><strong>No project selected</strong><p>Complete step 2 before binding a group.</p></div>`:""}<div class="setup-actions"><button class="button secondary" id="setup-bind-group" ${!s.whatsapp||!s.project?"disabled":""}>Discover and bind group</button>${s.groups.length?`<button class="button primary" data-setup-step="4">Continue to test</button>`:""}</div></div>`}
function setupTestPanel(s){const incidents=s.project?state.incidents.filter(i=>i.projectId===s.project.id).slice(0,3):[];return `<div class="setup-panel-head"><p class="eyebrow">FINAL CHECK</p><h2>Run a real mention test</h2><p>This checks the same path your partners will use, without granting any deployment authority.</p></div><div class="setup-panel-body"><div class="setup-relations">${setupCheck(s.whatsapp,"WhatsApp account connected",s.whatsapp?"Gateway is online":"Return to step 1")}${setupCheck(Boolean(s.project),"Project selected",s.project?.name||"Return to step 2")}${setupCheck(s.groups.length>0,"Group bound",s.groups.length?`${s.groups[0].groupName} will accept mentions`:"Return to step 4")}${setupCheck(s.repos.length>0,"Repository linked",s.repos.length?"Code-aware diagnosis is available":"Optional for intake testing")}${setupCheck(s.owner,"Owner selected",s.owner?`${state.ownerSettings.displayName||state.ownerSettings.jid} receives private updates`:"Message Echo directly, then select yourself under WhatsApp")}</div>${!s.owner?`<div class="setup-warning"><strong>Select an owner for private updates and approvals</strong><p>Send Echo a direct WhatsApp message, refresh the WhatsApp page, and select your discovered contact as owner.</p><button class="button secondary" data-go="channels">Configure owner</button></div>`:""}${s.intakeReady?`<div class="test-script"><p class="eyebrow">SEND THIS IN ${escapeHTML(s.groups[0].groupName)}</p><blockquote>Tap @, select Echo’s contact, then send: “The lead form is blank after I submit it. It started today on the contact page.”</blockquote><p>Expected: Echo acknowledges in the group, creates an incident, runs available analysis${s.owner?", and sends the owner a private summary":". Private summaries begin after an owner is selected"}.</p></div><div class="setup-actions"><button class="button primary" data-go="incidents">Watch incidents</button><button class="button secondary" id="refresh-test">Refresh results</button></div>`:`<div class="setup-warning"><strong>Message intake is not ready yet</strong><p>Connect WhatsApp, select a project and bind at least one group. Repository access is not required for this first test.</p></div><button class="button primary" data-setup-step="${recommendedIntakeStep()}">Finish required setup</button>`}${incidents.length?`<div class="setup-results"><h3>Latest project incidents</h3>${incidentTable(incidents)}</div>`:""}</div>`}

function renderOverview(){const d=state.dashboard;const recent=state.incidents.slice(0,6);return `${setupBanner()}<div class="metric-grid">${metric("Open incidents",d.openIncidents,"Reports requiring attention","--blue")}${metric("Open alerts",d.openAlerts,"Runtime conditions requiring attention",d.openAlerts?"--coral":"--mint")}${metric("Pending approvals",d.pendingApprovals,"No action runs without consent","--amber")}${metric("Running jobs",d.runningJobs,"Durable background work","--mint")}${metric("Failed deployments",d.failedDeployments,"Across all environments","--coral")}${metric("Active projects",d.enabledProjects,"Group-to-code mappings","--mint")}</div><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Recent incidents</h2><p>WhatsApp reports and their current control state</p></div><button class="quiet" data-go="incidents">View all</button></div>${incidentTable(recent)}</section><section class="card"><div class="card-head"><div><h2>Operational posture</h2><p>Trust boundaries at a glance</p></div></div><div class="card-body timeline"><div class="timeline-item"><i></i><div><strong>Service monitoring</strong><p>${d.openAlerts} open alerts across ${state.services.filter(s=>s.enabled).length} enabled services.</p></div></div><div class="timeline-item"><i></i><div><strong>WhatsApp gateway</strong><p>${escapeHTML(state.whatsapp.status)} · session messages remain isolated from repository credentials.</p></div></div><div class="timeline-item"><i></i><div><strong>Policy engine</strong><p>${d.pendingApprovals} actions waiting. Production always requires a separate exact-action approval.</p></div></div><div class="timeline-item"><i></i><div><strong>Repository access</strong><p>${state.repos.filter(r=>r.enabled).length} enabled repositories, ${state.repos.filter(r=>r.readOnly).length} read-only.</p></div></div><div class="timeline-item"><i></i><div><strong>Audit coverage</strong><p>${state.audit.length} recent immutable events available for review.</p></div></div></div></section></div>`}
function metric(label,value,note,accent){return `<article class="metric accent-${escapeHTML(accent.replace("--",""))}"><small>${label}</small><strong>${value}</strong><span>${note}</span></article>`}
function incidentTable(items){if(!items.length)return empty("No incidents yet","Mention Echo in a configured WhatsApp group to create one.");return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Incident</th><th>Project</th><th>Status</th><th>Severity</th><th>Reported</th></tr></thead><tbody>${items.map(i=>`<tr data-incident="${i.id}"><td><span class="primary-text">${escapeHTML(i.summary)}</span><span class="secondary-text">${i.id} · ${escapeHTML(i.reporterName||i.reporterJid)}</span></td><td>${escapeHTML(i.projectName)}</td><td>${badge(i.status)}</td><td><span class="priority ${i.severity}">${escapeHTML(i.severity)}</span></td><td>${when(i.createdAt)}</td></tr>`).join("")}</tbody></table></div>`}

function renderIncidents(){const filtered=state.incidentFilter?state.incidents.filter(i=>i.status===state.incidentFilter):state.incidents;return `<div class="toolbar"><p>${filtered.length} of ${state.incidents.length} reports shown.</p><div class="filter-row"><select id="incident-filter"><option value="">All states</option>${["reported","triaging","awaiting_owner","change_approved","patching","staging","staging_verified","production","resolved","failed"].map(v=>`<option value="${v}" ${state.incidentFilter===v?"selected":""}>${v.replaceAll("_"," ")}</option>`).join("")}</select></div></div><section class="card" id="incident-list">${incidentTable(filtered)}</section>`}
async function openIncident(id){
  try{
    const data=await api(`/api/v1/incidents/${id}`);
    const i=data.incident,a=data.analysis,changes=data.changeSets||[],deployments=data.deployments||[];
    const latest=changes[0];
    const projectRepos=state.repos.filter(r=>r.projectId===i.projectId&&r.enabled);
    const writableRepos=projectRepos.filter(r=>!r.readOnly);
    const proposedName=(a?.proposal?.repository||"").toLowerCase();
    const proposedRepo=projectRepos.find(r=>`${r.owner}/${r.name}`.toLowerCase()===proposedName)||(projectRepos.length===1?projectRepos[0]:null);
    const staging=state.environments.find(e=>e.projectId===i.projectId&&e.name.toLowerCase()==="staging");
    const production=state.environments.find(e=>e.projectId===i.projectId&&e.name.toLowerCase()==="production");
    const proposal=a?.proposal;
    const mergeApproval=state.approvals.find(item=>item.incidentId===i.id&&item.actionType==="merge_production"&&["pending","approved"].includes(item.status));
    const productionDeployment=deployments.find(item=>item.environment==="production");
    const proposalDetails=proposal?`<div class="risk"><b>Proposed action</b><p>${escapeHTML(proposal.description||proposal.action||"Review required")}</p>${(proposal.risks||[]).length?`<b>Risks</b><ul>${proposal.risks.map(v=>`<li>${escapeHTML(v)}</li>`).join("")}</ul>`:""}${(proposal.tests||[]).length?`<b>Validation</b><ul>${proposal.tests.map(v=>`<li>${escapeHTML(v)}</li>`).join("")}</ul>`:""}</div>`:"";
    let patchControl="";
    if(a&&!latest){
      if(writableRepos.length){
        patchControl=`<button class="button primary full" data-request-patch="${i.id}">Request patch approval</button><p class="muted">This creates a one-time approval request. Echo sends explicit APPROVE and REJECT reply options to the owner; no code changes happen until approval.</p>`;
      }else if(proposedRepo?.readOnly){
        patchControl=`<div class="setup-warning"><strong>Patch preparation is locked</strong><p>${escapeHTML(proposedRepo.owner)}/${escapeHTML(proposedRepo.name)} is read-only. Enable approved changes only if you want Echo to create a draft fix.</p></div><button class="button secondary full" data-edit-repository="${proposedRepo.id}">Review repository access</button>`;
      }else{
        patchControl=`<div class="setup-warning"><strong>No write-gated repository</strong><p>Configure the proposed repository before Echo can prepare a draft patch.</p></div><button class="button secondary full" data-go="repositories">Open repositories</button>`;
      }
    }
    let repositoryProduction="";
    if(latest&&!staging&&!productionDeployment){
      if(mergeApproval?.status==="pending")repositoryProduction=`<div class="setup-warning"><strong>Production approval requested</strong><p>Check WhatsApp for the one-time APPROVE or REJECT command.</p></div>`;
      else if(mergeApproval?.status==="approved"||i.status==="production")repositoryProduction=`<div class="setup-callout"><strong>Merge and production deployment in progress</strong><p>Echo is monitoring the repository's existing main-branch workflow and will report the verified result.</p></div>`;
      else if(["testing","ready"].includes(latest.status))repositoryProduction=`<div class="setup-warning"><strong>This project has no staging environment</strong><p>The separate production approval will verify GitHub checks, merge only commit ${escapeHTML(latest.commitSha.slice(0,12))}, and monitor the repository's existing main-branch deployment workflow.</p></div><button class="button danger full" data-request-merge="${i.id}" data-change-set="${latest.id}">Request merge and production deploy</button>`;
    }
    if(productionDeployment)repositoryProduction=`<div class="setup-${productionDeployment.status==="verified"?"success compact":"callout"}"><div><strong>Production ${escapeHTML(productionDeployment.status)}</strong><p>${escapeHTML(productionDeployment.artifactRef)}${productionDeployment.workflowUrl?` · <a href="${escapeHTML(productionDeployment.workflowUrl)}" target="_blank" rel="noreferrer">workflow run</a>`:""}</p></div></div>`;
    openModal("INCIDENT",id,`<div class="detail-grid"><div><p class="eyebrow">ORIGINAL REPORT</p><div class="report">${escapeHTML(i.sourceBody)}</div><hr><p class="eyebrow">LATEST ANALYSIS</p>${a?`<h3>${escapeHTML(a.summary)}</h3><p class="muted">Confidence: ${escapeHTML(a.confidence)} · ${when(a.createdAt)}</p><div class="evidence-list">${(a.evidence||[]).map(e=>`<div class="evidence"><code>${escapeHTML(e.repository)} · ${escapeHTML(e.path)}</code><p>${escapeHTML(e.finding)}</p></div>`).join("")||empty("No direct evidence","Echo needs more operational detail.")}</div>`:empty("Analysis queued","The worker has not completed repository analysis yet.")}${latest?`<hr><p class="eyebrow">CHANGE SET</p><a href="${escapeHTML(latest.pullRequestUrl)}" target="_blank" rel="noreferrer">Pull request #${latest.pullRequestNumber}</a><p class="muted">${escapeHTML(latest.commitSha)} · ${escapeHTML(latest.status)}</p>`:""}</div><div><div class="card-body"><p class="eyebrow">CONTROL STATE</p><p>${badge(i.status)} ${badge(i.severity)}</p><dl><dt>Project</dt><dd>${escapeHTML(i.projectName)}</dd><dt>Reporter</dt><dd>${escapeHTML(i.reporterName||i.reporterJid)}</dd><dt>Reported</dt><dd>${when(i.createdAt)}</dd></dl>${proposalDetails}${patchControl}${latest&&staging?`<button class="button primary full" data-request-deploy="${i.id}" data-environment="${staging.id}" data-artifact="${latest.artifactRef}" data-kind="deploy_staging">Request staging</button>`:""}${i.status==="staging_verified"&&latest&&production?`<button class="button danger full" data-request-deploy="${i.id}" data-environment="${production.id}" data-artifact="${latest.artifactRef}" data-kind="deploy_production">Request production</button>`:""}${repositoryProduction}<p class="muted">${deployments.length} deployment records</p></div></div></div>`);
  }catch(err){toast(err.message)}
}

function approvalDescription(a){const action=a.action||{};if(a.actionType==="merge_production")return `${action.repositoryFullName||"repository"} · PR #${action.pullRequestNumber||"?"} · commit ${String(action.headSha||"").slice(0,12)}`;if(a.actionType==="prepare_patch")return action.repositoryFullName||action.repository||`Action ${a.actionHash.slice(0,12)}`;if(a.actionType.startsWith("deploy_"))return `${a.actionType.replace("deploy_","")} · commit ${String(action.artifactRef||"").slice(0,12)}`;return `Action ${a.actionHash.slice(0,12)}`}
function renderApprovals(){const pending=state.approvals.filter(a=>a.status==="pending");return `<div class="toolbar"><p>Each approval is bound to an incident, exact action, actor, and expiry.</p></div><section class="card">${state.approvals.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Action</th><th>Incident</th><th>Requested by</th><th>Expires</th><th>Status</th><th></th></tr></thead><tbody>${state.approvals.map(a=>`<tr><td><span class="primary-text">${escapeHTML(a.actionType.replaceAll("_"," "))}</span><span class="secondary-text">${escapeHTML(approvalDescription(a))}</span></td><td>${escapeHTML(a.incidentId)}</td><td>${escapeHTML(a.requestedBy)}</td><td>${when(a.expiresAt)}</td><td>${badge(a.status)}</td><td>${a.status==="pending"?`<button class="button primary" data-approval="${a.id}" data-resolution="approved">Approve</button> <button class="button danger" data-approval="${a.id}" data-resolution="rejected">Reject</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:empty("No approval history","Approval requests will appear here before any code or deployment action.")}</section>${pending.length?`<p class="risk">Approving authorizes only the exact repository, pull request and commit shown. It does not grant open-ended repository or deployment access.</p>`:""}`}

function renderProjects(){return `<div class="toolbar"><p>A project is the hub that connects a team’s WhatsApp groups, code and deployment environments.</p><button class="button primary" id="add-project">Add project</button></div><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Configured projects</h2><p>${state.projects.filter(p=>p.enabled).length} enabled</p></div></div>${state.projects.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Project</th><th>State</th><th>Repositories</th><th>Groups</th><th>Setup</th></tr></thead><tbody>${state.projects.map(p=>{const repos=state.repos.filter(r=>r.projectId===p.id&&r.enabled).length;const groups=state.groups.filter(g=>g.projectId===p.id&&g.enabled).length;return `<tr data-project-setup="${p.id}"><td><span class="primary-text">${escapeHTML(p.name)}</span><span class="secondary-text">${escapeHTML(p.description||p.key)}</span></td><td>${badge(p.enabled?"enabled":"disabled")}</td><td>${repos}</td><td>${groups}</td><td>${badge(repos&&groups?"ready":"incomplete")}</td></tr>`}).join("")}</tbody></table></div>`:empty("No projects","Use Guided setup to create the first project, link its code and bind its group.")}</section><section class="card"><div class="card-head"><div><h2>How projects work</h2><p>The relationships Echo follows for every report</p></div><button class="quiet" data-resume-setup>Open guide</button></div><div class="card-body timeline"><div class="timeline-item"><i></i><div><strong>WhatsApp group → project</strong><p>Each bound group routes mentions into one project. A project may have multiple groups.</p></div></div><div class="timeline-item"><i></i><div><strong>Project → code graph</strong><p>Link the application, shared base, plugins and infrastructure Echo may inspect.</p></div></div><div class="timeline-item"><i></i><div><strong>Project → environments</strong><p>Staging and production remain separate, approval-gated delivery targets.</p></div></div></div></section></div>`}

function intakeReason(reason){return({echo_not_mentioned:"Echo received the message, but WhatsApp did not mark Echo as mentioned.",echo_identity_unavailable:"Echo received the message before its linked-device identity was ready.",binding_disabled:"Echo received the message, but this group binding is disabled.",empty_message:"Echo received a message type with no supported text or caption.",not_a_group_message:"The message was not a group report."})[reason]||String(reason||"Message rejected by intake policy.").replaceAll("_"," ")}
function latestIntakeEvent(){return state.audit.find(a=>["incident.reported","message.ignored"].includes(a.action))}
function intakeDetails(a){if(!a)return"";const metadata=a.metadata&&typeof a.metadata==="object"?a.metadata:{};if(a.action==="message.ignored")return intakeReason(metadata.reason);if(a.action==="incident.reported")return"Accepted and created an incident.";return""}
function contactLabel(contact){return contact.displayName?`${contact.displayName} · ${contact.jid}`:contact.jid}
function ownerCard(){const owner=state.ownerSettings;const discovered=state.contacts.slice(0,5);return `<section class="card owner-card"><div class="card-head"><div><h2>Owner contact</h2><p>Private diagnoses, approval codes and deployment results go only to this person</p></div>${owner?.configured?badge("configured"):badge("required")}</div><div class="card-body">${owner?.configured?`<div class="setup-success compact"><span>✓</span><div><strong>${escapeHTML(owner.displayName||owner.jid)}</strong><p>${escapeHTML(owner.jid)} · ${owner.source==="application"?"selected in Echo":"environment fallback"}</p></div></div>`:`<div class="setup-warning"><strong>No owner selected</strong><p>Send Echo a direct WhatsApp message first. Echo will confirm discovery, then the contact will appear here.</p></div>`}${discovered.length?`<div class="setup-list">${discovered.map(c=>`<div><span class="setup-list-icon">●</span><p><strong>${escapeHTML(c.displayName||c.jid)}</strong><small>${escapeHTML(c.jid)} · ${c.messageCount} direct ${c.messageCount===1?"message":"messages"} · last seen ${when(c.lastSeenAt)}</small></p>${c.id===owner?.contactId?badge("owner"):""}</div>`).join("")}</div>`:`<p class="muted">No direct-message contacts discovered yet. Group participants are deliberately not collected.</p>`}<div class="setup-actions"><button class="button ${owner?.configured?"secondary":"primary"}" id="configure-owner" ${discovered.length?"":"disabled"}>${owner?.configured?"Change owner":"Select owner"}</button>${owner?.source==="application"?`<button class="button danger" id="clear-owner">Clear owner</button>`:""}<button class="quiet" id="refresh-contacts">Refresh contacts</button></div></div></section>`}
function intakeDiagnosticCard(){const event=latestIntakeEvent();return `<section class="card intake-diagnostic"><div class="card-head"><div><h2>Last message intake result</h2><p>Confirms whether Echo received and accepted the latest relevant group message</p></div><button class="quiet" id="refresh-intake">Refresh</button></div><div class="card-body">${event?`<div class="setup-${event.action==="incident.reported"?"success compact":"warning"}">${event.action==="incident.reported"?"<span>✓</span>":""}<div><strong>${event.action==="incident.reported"?"Report accepted":"Message received but ignored"}</strong><p>${escapeHTML(intakeDetails(event))} · ${when(event.createdAt)}</p></div></div>`:`<div class="setup-callout"><strong>No bound-group message has been observed yet</strong><p>Send a new message by tapping @ and selecting Echo’s contact, then refresh. Echo will now show an explicit result here if intake policy rejects it.</p></div>`}</div></section>`}
function renderChannels(){const w=state.whatsapp;const waiting=["pairing_requested","pairing","connecting"].includes(w.status);const session=w.qrCode?`<div class="qr-box" aria-live="polite"><p>Open WhatsApp on the dedicated number, then choose <b>Linked devices → Link a device</b>.</p><img src="/api/v1/whatsapp/qr.png?v=${encodeURIComponent(w.updatedAt||Date.now())}" alt="Fresh WhatsApp pairing QR code"><p class="muted">Echo automatically replaces this image when WhatsApp rotates the code. Treat it as a secret.</p></div>`:w.status==="connected"?`<div class="feature-grid"><div class="feature"><strong>Device identity</strong><p>${escapeHTML(w.deviceJid||"Connected")}</p></div><div class="feature"><strong>Last event</strong><p>${escapeHTML(w.lastEvent||"connected")}</p></div><div class="feature"><strong>Connected</strong><p>${when(w.connectedAt)}</p></div><div class="feature"><strong>Last error</strong><p>${escapeHTML(w.lastError||"None")}</p></div></div>`:`<div class="link-device"><h3>${waiting?"Preparing a fresh pairing code":"Link the dedicated Echo number"}</h3><p class="muted">A code is generated only when you request one, so an old code is never left waiting on this screen.</p>${w.lastError?`<p class="form-error">${escapeHTML(w.lastError)}</p>`:""}<button class="button primary" id="link-device" ${waiting?"disabled":""}>${waiting?"Preparing…":"Link device"}</button></div>`;return `<div class="grid-2"><section class="card"><div class="card-head"><div><h2>WhatsApp session</h2><p>HyperMeow connection backed by isolated MariaDB state</p></div>${badge(w.status)}</div><div class="card-body">${session}</div></section><section class="card"><div class="card-head"><div><h2>Group bindings</h2><p>Only real mention metadata opens an incident</p></div><button class="button primary" id="add-group">Bind group</button></div>${state.groups.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Group</th><th>Project</th><th>Mention</th><th>State</th></tr></thead><tbody>${state.groups.map(g=>`<tr><td><span class="primary-text">${escapeHTML(g.groupName)}</span><span class="secondary-text">${escapeHTML(g.groupJid)}</span></td><td>${escapeHTML(g.projectName)}</td><td>${g.mentionRequired?"Required":"Any message"}</td><td>${badge(g.enabled?"enabled":"disabled")}</td></tr>`).join("")}</tbody></table></div>`:empty("No group bindings","Pair Echo, add it to a group, then bind that group JID to a project.")}</section></div>${ownerCard()}${intakeDiagnosticCard()}`}

function renderRepositories(){const connected=Boolean(state.githubSettings?.configured);return `<div class="github-connection ${connected?"connected":"missing"}"><div><p class="eyebrow">GITHUB CONNECTION</p><h2>${connected?`Connected as ${escapeHTML(state.githubSettings.account||"GitHub user")}`:"Token not configured"}</h2><p>${connected?`The token is encrypted at rest · updated ${when(state.githubSettings.updatedAt)}.`:"Add a fine-grained token limited to the repositories Echo may inspect."}</p></div><div class="setup-actions"><button class="button ${connected?"secondary":"primary"}" id="configure-github-token">${connected?"Replace token":"Configure token"}</button>${connected?`<button class="button danger" id="remove-github-token">Remove</button>`:""}</div></div><div class="toolbar"><p>Click a repository to review or change its access policy.</p><button class="button primary" id="add-repo" ${connected?"":"disabled"}>Add repository</button></div><section class="card">${state.repos.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Repository</th><th>Project</th><th>Role</th><th>Access</th><th>Branch</th><th>State</th></tr></thead><tbody>${state.repos.map(r=>`<tr data-repository="${r.id}"><td><span class="primary-text">${escapeHTML(r.owner)}/${escapeHTML(r.name)}</span><span class="secondary-text">Click to edit access</span></td><td>${escapeHTML(state.projects.find(p=>p.id===r.projectId)?.name||r.projectId)}</td><td>${badge(r.role)}</td><td>${badge(r.readOnly?"read only":"approved changes")}</td><td><code>${escapeHTML(r.defaultBranch)}</code></td><td>${badge(r.enabled?"enabled":"disabled")}</td></tr>`).join("")}</tbody></table></div>`:empty("No repositories",connected?"Add a selected GitHub repository to enable evidence collection.":"Configure a GitHub token first, then link selected repositories.")}</section><p class="risk">Use a fine-grained token limited to selected repositories. Approved patching and merging need Contents: write and Pull requests: write. Existing-workflow monitoring needs Actions: read; Echo-dispatched workflows need Actions: write.</p>`}

function renderMonitoring(){const openCritical=state.alerts.filter(a=>a.severity==="critical").length;return `<div class="metric-grid">${metric("Open alerts",state.alerts.length,state.alerts.length?"Needs attention":"All clear",state.alerts.length?"--amber":"--mint")}${metric("Critical",openCritical,openCritical?"Immediate review":"None open",openCritical?"--rose":"--mint")}${metric("Services",state.services.filter(s=>s.enabled).length,"Enabled catalogue entries","--blue")}${metric("Monitor intake",state.bootstrap.features.monitor?"enabled":"disabled",state.bootstrap.features.monitor?"Signed webhook active":"Configure webhook secret",state.bootstrap.features.monitor?"--mint":"--amber")}</div><div class="toolbar"><p>Health events are accepted only through the signed, idempotent monitor webhook.</p><button class="button primary" id="add-service">Add service</button></div><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Open alerts</h2><p>Meaningful state transitions notify the WhatsApp owner</p></div></div>${state.alerts.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>Severity</th><th>Summary</th><th>Last seen</th></tr></thead><tbody>${state.alerts.map(a=>`<tr><td class="primary-text">${escapeHTML(a.serviceName)}</td><td>${badge(a.severity)}</td><td>${escapeHTML(a.summary)}</td><td>${when(a.lastSeenAt)}</td></tr>`).join("")}</tbody></table></div>`:empty("No open alerts","Echo will show degraded and unhealthy service signals here.")}</section><section class="card"><div class="card-head"><div><h2>Recent signals</h2><p>Latest observer evidence</p></div></div>${state.monitorEvents.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>Status</th><th>Source</th><th>Observed</th></tr></thead><tbody>${state.monitorEvents.slice(0,20).map(e=>`<tr><td><span class="primary-text">${escapeHTML(e.serviceName)}</span><span class="secondary-text">${escapeHTML(e.summary)}</span></td><td>${badge(e.status)}</td><td>${escapeHTML(e.source)}</td><td>${when(e.observedAt)}</td></tr>`).join("")}</tbody></table></div>`:empty("No signals yet","Connect a local observer after adding the first service.")}</section></div><section class="card"><div class="card-head"><div><h2>Service catalogue</h2><p>The stable map between projects and runtime workloads</p></div></div>${state.services.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>Project</th><th>Kind</th><th>Criticality</th><th>State</th></tr></thead><tbody>${state.services.map(s=>`<tr><td><span class="primary-text">${escapeHTML(s.name)}</span><span class="secondary-text">${escapeHTML(s.key)} · ${escapeHTML(s.description||"No description")}</span></td><td>${escapeHTML(s.projectName||s.projectId)}</td><td>${badge(s.kind)}</td><td>${badge(s.criticality)}</td><td>${badge(s.enabled?"enabled":"disabled")}</td></tr>`).join("")}</tbody></table></div>`:empty("No services","Add a service to give monitoring and investigations a stable operational target.")}</section>`}

function renderEnvironments(){return `<div class="toolbar"><p>Protected environments dispatch CI workflows with immutable artifact references.</p><button class="button primary" id="add-environment">Add environment</button></div><section class="card">${state.environments.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Environment</th><th>Project</th><th>Adapter</th><th>Approval</th><th>Protection</th></tr></thead><tbody>${state.environments.map(e=>`<tr><td class="primary-text">${escapeHTML(e.name)}</td><td>${escapeHTML(state.projects.find(p=>p.id===e.projectId)?.name||e.projectId)}</td><td>${badge(e.kind)}</td><td>${e.requiresApproval?"Required":"Disabled"}</td><td>${badge(e.protected?"protected":"unprotected")}</td></tr>`).join("")}</tbody></table></div>`:empty("No environments","Configure staging first, then production with a separate protected workflow.")}</section>`}
function renderDeployments(){return `<div class="toolbar"><p>Only explicitly approved, immutable artifacts are dispatched.</p></div><section class="card">${state.deployments.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Operation</th><th>Environment</th><th>Incident</th><th>Artifact</th><th>Status</th><th>Created</th></tr></thead><tbody>${state.deployments.map(d=>`<tr><td>${badge(d.operation||"deploy")}</td><td class="primary-text">${escapeHTML(d.environment)}</td><td>${escapeHTML(d.incidentId)}</td><td><code>${escapeHTML((d.artifactRef||"").slice(0,18))}…</code></td><td>${badge(d.status)}</td><td>${when(d.createdAt)}</td></tr>`).join("")}</tbody></table></div>`:empty("No deployments","Staging, production, and rollback dispatches will appear here with verification results.")}</section>`}

function renderAudit(){return `<div class="toolbar"><p>Recent security-relevant state transitions and external mutations.</p></div><section class="card">${state.audit.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Resource</th><th>Details</th><th>Outcome</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${when(a.createdAt)}</td><td><span class="primary-text">${escapeHTML(a.actorId)}</span><span class="secondary-text">${escapeHTML(a.actorType)}</span></td><td>${escapeHTML(a.action)}</td><td>${escapeHTML(a.resourceType)} · ${escapeHTML(a.resourceId)}</td><td>${escapeHTML(intakeDetails(a)||"—")}</td><td>${badge(a.outcome)}</td></tr>`).join("")}</tbody></table></div>`:empty("No audit events","Events will appear when reports, configuration, approvals and actions occur.")}</section>`}
function renderSystem(){const f=state.bootstrap.features;const ai=state.aiSettings;const provider=ai?.provider==="openai"?"OpenAI":"OpenAI-compatible fallback";return `<div class="github-connection ${ai?.configured?"connected":"missing"}"><div><p class="eyebrow">AI CONNECTION</p><h2>${ai?.configured?`${provider} · ${escapeHTML(ai.model)}`:"OpenAI not configured"}</h2><p>${ai?.configured?`API key ${ai.source==="application"?`encrypted in Echo · updated ${when(ai.updatedAt)}`:"provided by the environment"}.`:"Add the OpenAI key Echo should use for repository-backed diagnosis and patch planning."}</p></div><div class="setup-actions"><button class="button ${ai?.configured?"secondary":"primary"}" id="configure-ai">${ai?.source==="application"?"Replace key":"Configure OpenAI"}</button>${ai?.source==="application"?`<button class="button danger" id="remove-ai">Remove</button>`:""}</div></div><div class="metric-grid">${metric("WhatsApp",state.whatsapp.status,"Single active session","--mint")}${metric("Core database","ready","MariaDB migrations current","--mint")}${metric("AI analysis",f.ai?"enabled":"disabled",ai?.model||"Advisory only","--blue")}${metric("GitHub",f.github?"connected":"missing",f.github?`Token for ${state.githubSettings?.account||"account"}`:"Configure in Repositories","--amber")}${metric("Worker",f.worker?"enabled":"disabled","Durable job leases","--mint")}</div><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Trust boundaries</h2><p>Credentials are deliberately separated</p></div></div><div class="card-body feature-grid"><div class="feature"><strong>Gateway</strong><p>WhatsApp session only. No repository credentials.</p></div><div class="feature"><strong>Control plane</strong><p>Policy, approvals, encrypted settings and audit.</p></div><div class="feature"><strong>Workers</strong><p>Disposable repository workspaces with bounded evidence.</p></div><div class="feature"><strong>Deployments</strong><p>CI adapters receive immutable artifact references.</p></div></div></section><section class="card"><div class="card-head"><div><h2>Environment</h2><p>Current runtime posture</p></div></div><div class="card-body"><p class="report">${escapeHTML(state.bootstrap.environment)}\nPublic UI session: authenticated\nCSRF protection: enabled\nEncrypted settings: enabled\nContent security policy: enabled\nAudit logging: enabled</p></div></section></div>`}

function openModal(kicker,title,body){$("#modal-kicker").textContent=kicker;$("#modal-title").textContent=title;$("#modal-body").innerHTML=body;$("#modal").showModal()}
function projectOptions(selected=""){return state.projects.map(p=>`<option value="${p.id}" ${p.id===selected?"selected":""}>${escapeHTML(p.name)}</option>`).join("")}
function projectForm(){openModal("CONFIGURATION","Add project",`<form id="project-form"><div class="field-row"><label>Name<input name="name" required placeholder="Team Nudgie"></label><label>Key<input name="key" required placeholder="nudgie"></label></div><label>Description<textarea name="description" placeholder="Site, plugins and deployment relationship"></textarea></label><label><span><input type="checkbox" name="enabled" checked> Enabled</span></label><div class="modal-actions"><button class="button secondary" type="button" data-close>Cancel</button><button class="button primary">Save project</button></div></form>`)}
function groupForm(discovered=[],projectId=""){const discovery=discovered.length?`<label>Joined WhatsApp group<select id="discovered-group"><option value="">Choose a discovered group</option>${discovered.filter(g=>!g.suspended).map(g=>`<option value="${escapeHTML(g.jid)}" data-name="${escapeHTML(g.name)}">${escapeHTML(g.name)} · ${g.participantCount} participants</option>`).join("")}</select></label>`:`<p class="muted">No joined groups were discovered. Confirm that Echo’s connected account is a participant, then try again. You may also enter the group details manually.</p>`;openModal("WHATSAPP","Bind a group",`<form id="group-form"><label>Project<select name="projectId" required><option value="">Choose project</option>${projectOptions(projectId)}</select></label>${discovery}<div class="field-row"><label>Group name<input id="group-name" name="groupName" required placeholder="Team Nudgie"></label><label>Group JID<input id="group-jid" name="groupJid" required placeholder="1203630…@g.us"></label></div><label>Acknowledgement<textarea name="ackTemplate">Thanks — I have logged this report and will investigate it privately with the owner.</textarea></label><div class="field-row"><label><span><input type="checkbox" name="mentionRequired" checked> Require actual mention</span></label><label><span><input type="checkbox" name="enabled" checked> Enabled</span></label></div><div class="modal-actions"><button class="button secondary" type="button" data-close>Cancel</button><button class="button primary">Save binding</button></div></form>`)}
function repoForm(projectId="",repository=null){const roles=["application","base","plugin","infrastructure","documentation"];const selectedProject=repository?.projectId||projectId;openModal("GITHUB",repository?"Edit repository access":"Add repository",`<form id="repo-form">${repository?`<input type="hidden" name="id" value="${escapeHTML(repository.id)}">`:""}<label>Project<select name="projectId" required><option value="">Choose project</option>${projectOptions(selectedProject)}</select></label><div class="field-row"><label>Owner<input name="owner" required value="${escapeHTML(repository?.owner||"")}" placeholder="ReindeerGames"></label><label>Repository<input name="name" required value="${escapeHTML(repository?.name||"")}" placeholder="wpretreats"></label></div><div class="field-row"><label>Role<select name="role">${roles.map(role=>`<option ${repository?.role===role?"selected":""}>${role}</option>`).join("")}</select></label><label>Default branch<input name="defaultBranch" value="${escapeHTML(repository?.defaultBranch||"main")}" required></label></div><div class="field-row"><label><span><input type="checkbox" name="readOnly" ${repository?.readOnly!==false?"checked":""}> Read-only investigation only</span></label><label><span><input type="checkbox" name="enabled" ${repository?.enabled!==false?"checked":""}> Enabled</span></label></div><div class="setup-warning"><strong>${repository?.readOnly!==false?"Patch preparation is currently locked":"Approved changes are enabled"}</strong><p>Clear “Read-only investigation only” to let Echo create draft changes after a separate, one-time owner approval. This does not permit automatic deployment.</p></div><div class="modal-actions"><button class="button secondary" type="button" data-close>Cancel</button><button class="button primary">Save access policy</button></div></form>`)}
function githubTokenForm(){openModal("SECURE SETTINGS",state.githubSettings?.configured?"Replace GitHub token":"Connect GitHub",`<form id="github-token-form"><div class="setup-warning"><strong>Use a fine-grained personal access token</strong><p>Select only the repositories Echo needs. For diagnosis grant Contents: read. Patch preparation and approved merging additionally need Contents: write and Pull requests: write. Monitoring existing workflows needs Actions: read; workflow dispatch needs Actions: write.</p></div><label>Fine-grained token<input name="token" type="password" required autocomplete="off" spellcheck="false" placeholder="github_pat_…"></label><p class="muted">Echo validates this token with GitHub before encrypting it. The value is never returned by the API and cannot be viewed again after saving.</p><div class="modal-actions"><button class="button secondary" type="button" data-close>Cancel</button><button class="button primary">Validate and save</button></div></form>`)}
function aiSettingsForm(){const model=state.aiSettings?.provider==="openai"?state.aiSettings.model:"gpt-5-mini";openModal("SECURE SETTINGS",state.aiSettings?.source==="application"?"Replace OpenAI key":"Configure OpenAI",`<form id="ai-settings-form"><div class="setup-warning"><strong>Repository evidence may be sent to OpenAI</strong><p>Echo sends the issue report and bounded text evidence from the project’s configured repositories. Secrets and oversized files are excluded by the worker’s evidence controls.</p></div><label>OpenAI API key<input name="apiKey" type="password" required autocomplete="off" spellcheck="false" placeholder="sk-…"></label><label>Model<input name="model" required value="${escapeHTML(model||"gpt-5-mini")}" placeholder="gpt-5-mini"></label><p class="muted">Echo validates the key and model against OpenAI, encrypts the key in MariaDB, and never returns it to the browser.</p><div class="modal-actions"><button class="button secondary" type="button" data-close>Cancel</button><button class="button primary">Validate and save</button></div></form>`)}
function ownerForm(){if(!state.contacts.length){toast("Send Echo a direct WhatsApp message first");return}openModal("WHATSAPP OWNER","Select owner",`<form id="owner-form"><div class="setup-warning"><strong>This contact controls sensitive approvals</strong><p>Only the selected owner can approve or reject actions through WhatsApp. Echo will send private incident analysis and deployment results to this contact.</p></div><label>Discovered contact<select name="contactId" required>${state.contacts.map(c=>`<option value="${escapeHTML(c.id)}" ${c.id===state.ownerSettings?.contactId?"selected":""}>${escapeHTML(contactLabel(c))}</option>`).join("")}</select></label><p class="muted">Contacts appear only after they message Echo directly. Group participants are not automatically collected.</p><div class="modal-actions"><button class="button secondary" type="button" data-close>Cancel</button><button class="button primary">Set as owner</button></div></form>`)}
function serviceForm(){openModal("OPERATIONS","Add service",`<form id="service-form"><label>Project<select name="projectId" required><option value="">Choose project</option>${projectOptions()}</select></label><div class="field-row"><label>Name<input name="name" required placeholder="Nudgie web"></label><label>Key<input name="key" required placeholder="nudgie-web"></label></div><div class="field-row"><label>Kind<select name="kind"><option>application</option><option>worker</option><option>database</option><option>platform</option><option>external</option></select></label><label>Criticality<select name="criticality"><option>low</option><option selected>medium</option><option>high</option><option>critical</option></select></label></div><label>Description<textarea name="description" placeholder="What this workload does and who depends on it"></textarea></label><label>Metadata JSON<textarea name="metadata" required>{}</textarea></label><label><span><input type="checkbox" name="enabled" checked> Accept monitoring events</span></label><div class="modal-actions"><button class="button secondary" type="button" data-close>Cancel</button><button class="button primary">Save service</button></div></form>`)}
function environmentForm(){openModal("DEPLOYMENT","Add environment",`<form id="environment-form"><label>Project<select name="projectId" required><option value="">Choose project</option>${projectOptions()}</select></label><div class="field-row"><label>Name<select name="name"><option>staging</option><option>production</option></select></label><label>Adapter<select name="kind"><option value="github_actions">GitHub Actions</option></select></label></div><label>Configuration JSON<textarea name="config" required>{"repositoryId":"","workflow":"deploy.yml","inputs":{}}</textarea></label><p class="muted">Echo dispatches the workflow from the immutable approved change branch so the completion webhook can be correlated to the exact artifact.</p><div class="field-row"><label><span><input type="checkbox" name="requiresApproval" checked> Require approval</span></label><label><span><input type="checkbox" name="protected" checked> Protected</span></label></div><div class="modal-actions"><button class="button secondary" type="button" data-close>Cancel</button><button class="button primary">Save environment</button></div></form>`)}
function patchApprovalForm(incidentId){const incident=state.incidents.find(i=>i.id===incidentId);const repos=state.repos.filter(r=>r.projectId===incident?.projectId&&r.enabled&&!r.readOnly);if(!repos.length){toast("Configure a write-gated repository for this project first");return}openModal("CONTROL GATE","Request patch approval",`<form id="patch-approval-form" data-incident-id="${escapeHTML(incidentId)}"><p class="muted">Choose the exact repository Echo may change. Approval remains bound to this incident and repository.</p><label>Repository<select name="repositoryId" required>${repos.map(r=>`<option value="${r.id}">${escapeHTML(r.owner)}/${escapeHTML(r.name)} · ${escapeHTML(r.role)}</option>`).join("")}</select></label><div class="modal-actions"><button class="button secondary" type="button" data-close>Cancel</button><button class="button primary">Create approval</button></div></form>`)}

document.addEventListener("click",async e=>{
  const nav=e.target.closest("[data-view]");
  if(nav){if(nav.dataset.view==="setup")state.setupStep=recommendedSetupStep();navigate(nav.dataset.view);return}
  const setupStep=e.target.closest("[data-setup-step]");
  if(setupStep){state.setupStep=Math.max(0,Math.min(4,Number(setupStep.dataset.setupStep)));if(state.view!=="setup")navigate("setup");else render();return}
  if(e.target.closest("[data-resume-setup]")){state.setupStep=recommendedSetupStep();navigate("setup");return}
  const go=e.target.closest("[data-go]");if(go){navigate(go.dataset.go);return}
  const projectSetup=e.target.closest("[data-project-setup]");if(projectSetup){state.setupProjectId=projectSetup.dataset.projectSetup;state.setupStep=recommendedSetupStep();navigate("setup");return}
  const incident=e.target.closest("[data-incident]");if(incident){openIncident(incident.dataset.incident);return}
  const editRepository=e.target.closest("[data-edit-repository],[data-repository]");if(editRepository){const repository=state.repos.find(r=>r.id===(editRepository.dataset.editRepository||editRepository.dataset.repository));if(repository){$("#modal").close();repoForm("",repository)}return}
  if(e.target.closest("#add-project")||e.target.closest("#setup-create-project")){projectForm();return}
  if(e.target.closest("#configure-github-token")){githubTokenForm();return}
  if(e.target.closest("#configure-ai")){aiSettingsForm();return}
  if(e.target.closest("#remove-ai")){if(!confirm("Remove Echo’s stored OpenAI key? Repository-backed analysis and patch planning will stop unless an environment fallback is configured."))return;try{await api("/api/v1/settings/ai",{method:"DELETE",body:"{}"});await refreshAll();render();toast("OpenAI key removed")}catch(err){toast(err.message)}return}
  if(e.target.closest("#configure-owner")){ownerForm();return}
  if(e.target.closest("#clear-owner")){if(!confirm("Clear the selected WhatsApp owner? Private updates and WhatsApp approvals will stop until another owner is selected."))return;try{await api("/api/v1/settings/owner",{method:"DELETE",body:"{}"});await refreshAll();render();toast("Owner cleared")}catch(err){toast(err.message)}return}
  if(e.target.closest("#remove-github-token")){if(!confirm("Remove Echo’s stored GitHub token? Repository diagnosis, patching and deployments will stop until another token is configured."))return;try{await api("/api/v1/settings/github",{method:"DELETE",body:"{}"});await refreshAll();render();toast("GitHub token removed")}catch(err){toast(err.message)}return}
  const link=e.target.closest("#link-device");
  if(link){link.disabled=true;try{state.whatsapp=await api("/api/v1/whatsapp/link",{method:"POST",body:"{}"});updateWhatsAppSummary();updateSetupProgress();render();monitorPairing()}catch(err){toast(err.message);link.disabled=false}return}
  if(e.target.closest("#add-group")||e.target.closest("#setup-bind-group")){let discovered=[];if(state.whatsapp.status==="connected"){try{discovered=await api("/api/v1/whatsapp/groups")||[]}catch(err){toast(err.message)}}groupForm(discovered,e.target.closest("#setup-bind-group")?selectedSetupProject()?.id||"":"");return}
  if(e.target.closest("#add-repo")||e.target.closest("#setup-add-repo")){repoForm(e.target.closest("#setup-add-repo")?selectedSetupProject()?.id||"":"");return}
  if(e.target.closest("#refresh-test,#refresh-intake,#refresh-contacts")){try{await refreshAll();render();toast("Data refreshed")}catch(err){toast(err.message)}return}
  if(e.target.closest("#add-service")){serviceForm();return}
  if(e.target.closest("#add-environment")){environmentForm();return}
  if(e.target.closest("[data-close]")){$("#modal").close();return}
  const approval=e.target.closest("[data-approval]");if(approval){approval.disabled=true;try{await api(`/api/v1/approvals/${approval.dataset.approval}/${approval.dataset.resolution}`,{method:"POST",body:"{}"});toast(`Approval ${approval.dataset.resolution}`);await refreshAll();render()}catch(err){toast(err.message)}return}
  const patch=e.target.closest("[data-request-patch]");if(patch){patchApprovalForm(patch.dataset.requestPatch);return}
  const merge=e.target.closest("[data-request-merge]");if(merge){merge.disabled=true;try{const result=await api(`/api/v1/incidents/${merge.dataset.requestMerge}/approvals`,{method:"POST",body:JSON.stringify({actionType:"merge_production",action:{changeSetId:merge.dataset.changeSet}})});toast(`Production approval created · code ${result.displayNonce}`);$("#modal").close();await refreshAll();navigate("approvals")}catch(err){merge.disabled=false;toast(err.message)}return}
  const deploy=e.target.closest("[data-request-deploy]");if(deploy){try{const action={environmentId:deploy.dataset.environment,artifactRef:deploy.dataset.artifact};if(deploy.dataset.kind==="deploy_production"){const staged=state.deployments.find(d=>d.incidentId===deploy.dataset.requestDeploy&&d.environment==="staging"&&d.status==="verified");if(!staged)throw new Error("A verified staging deployment is required");action.stagingDeploymentId=staged.id}const result=await api(`/api/v1/incidents/${deploy.dataset.requestDeploy}/approvals`,{method:"POST",body:JSON.stringify({actionType:deploy.dataset.kind,action})});toast(`Approval created · code ${result.displayNonce}`);$("#modal").close();await refreshAll();navigate("approvals")}catch(err){toast(err.message)}return}
});

document.addEventListener("change",e=>{if(e.target.id==="incident-filter"){state.incidentFilter=e.target.value;render();return}if(e.target.id==="setup-project-select"){state.setupProjectId=e.target.value;render();return}if(e.target.id!=="discovered-group")return;const option=e.target.selectedOptions[0];if(!option||!option.value)return;$("#group-jid").value=option.value;$("#group-name").value=option.dataset.name||option.textContent.split(" · ")[0]});

document.addEventListener("submit",async e=>{e.preventDefault();const form=e.target;if(form.id==="login-form"){try{await api("/api/v1/auth/login",{method:"POST",body:JSON.stringify({token:form.elements.namedItem("token").value})});$("#login-error").textContent="";await boot()}catch(err){$("#login-error").textContent=err.message};return}const fd=new FormData(form);const obj=Object.fromEntries(fd.entries());const checked=name=>Boolean(form.elements.namedItem(name)?.checked);const inSetup=state.view==="setup";try{if(form.id==="service-form"){obj.enabled=checked("enabled");obj.metadata=JSON.parse(obj.metadata);await api("/api/v1/services",{method:"POST",body:JSON.stringify(obj)})}if(form.id==="github-token-form"){const submit=form.querySelector("button[type=submit],button:not([type])");if(submit)submit.disabled=true;state.githubSettings=await api("/api/v1/settings/github",{method:"PUT",body:JSON.stringify({token:obj.token})});state.bootstrap.features.github=true;form.elements.namedItem("token").value="";$("#modal").close();toast(`GitHub connected as ${state.githubSettings.account}`);await refreshAll();render();return}if(form.id==="ai-settings-form"){const submit=form.querySelector("button[type=submit],button:not([type])");if(submit)submit.disabled=true;state.aiSettings=await api("/api/v1/settings/ai",{method:"PUT",body:JSON.stringify({apiKey:obj.apiKey,model:obj.model})});state.bootstrap.features.ai=true;form.elements.namedItem("apiKey").value="";$("#modal").close();toast(`OpenAI connected with ${state.aiSettings.model}`);await refreshAll();render();return}if(form.id==="owner-form"){state.ownerSettings=await api("/api/v1/settings/owner",{method:"PUT",body:JSON.stringify({contactId:obj.contactId})});state.bootstrap.features.owner=true;$("#modal").close();toast(`${state.ownerSettings.displayName||state.ownerSettings.jid} is now the owner`);await refreshAll();render();return}if(form.id==="project-form"){obj.enabled=checked("enabled");const saved=await api("/api/v1/projects",{method:"POST",body:JSON.stringify(obj)});state.setupProjectId=saved.id;if(inSetup)state.setupStep=2}if(form.id==="group-form"){obj.mentionRequired=checked("mentionRequired");obj.enabled=checked("enabled");await api("/api/v1/groups",{method:"POST",body:JSON.stringify(obj)});state.setupProjectId=obj.projectId;if(inSetup)state.setupStep=4}if(form.id==="repo-form"){const submit=form.querySelector("button[type=submit],button:not([type])");if(submit)submit.disabled=true;obj.readOnly=checked("readOnly");obj.enabled=checked("enabled");const saved=await api("/api/v1/repositories",{method:"POST",body:JSON.stringify(obj)});state.setupProjectId=saved.projectId;$("#modal").close();await refreshAll();render();toast(saved.readOnly?"Repository remains read-only":"Approved changes enabled; reopen the incident to request patch approval");return}if(form.id==="environment-form"){obj.requiresApproval=checked("requiresApproval");obj.protected=checked("protected");obj.config=JSON.parse(obj.config);await api("/api/v1/environments",{method:"POST",body:JSON.stringify(obj)})}if(form.id==="patch-approval-form"){const repo=state.repos.find(r=>r.id===obj.repositoryId);if(!repo)throw new Error("Repository is no longer available");const result=await api(`/api/v1/incidents/${form.dataset.incidentId}/approvals`,{method:"POST",body:JSON.stringify({actionType:"prepare_patch",action:{repositoryId:repo.id,repository:`${repo.owner}/${repo.name}`}})});toast(`Approval created · code ${result.displayNonce}`);$("#modal").close();await refreshAll();navigate("approvals");return}$("#modal").close();toast("Configuration saved");await refreshAll();render()}catch(err){const submit=form.querySelector("button[type=submit],button:not([type])");if(submit)submit.disabled=false;toast(err.message)}});

$("#refresh").addEventListener("click",async()=>{try{await refreshAll();render();toast("Data refreshed")}catch(err){toast(err.message)}});$("#mobile-menu").addEventListener("click",()=>$(".sidebar").classList.toggle("open"));$("#logout").addEventListener("click",async()=>{try{await api("/api/v1/auth/logout",{method:"POST",body:"{}"})}finally{showLogin()}});window.addEventListener("hashchange",()=>navigate(location.hash.slice(1)));boot();
